const lessons=[{"sentences":[{"speaker":"A","text":"Welcome to our weekly community information session about local leisure activities.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.520458333333333},{"speaker":"A","text":"Today I will explain how you can join our upcoming autumn programme.","position":2,"audioStartSeconds":5.720458333333333,"audioEndSeconds":10.18},{"speaker":"A","text":"We offer various outdoor sports and creative classes for residents of all ages.","position":3,"audioStartSeconds":10.38,"audioEndSeconds":15.7795},{"speaker":"A","text":"Our main office is situated inside the central park near the cafe.","position":4,"audioStartSeconds":15.9795,"audioEndSeconds":20.708875},{"speaker":"A","text":"Registration starts on Monday morning at nine o clock sharp.","position":5,"audioStartSeconds":20.908875,"audioEndSeconds":25.07125},{"speaker":"A","text":"You can register online through our website or visit us in person.","position":6,"audioStartSeconds":25.27125,"audioEndSeconds":29.67845833333333},{"speaker":"A","text":"Each adult participant must pay a small annual fee of twenty pounds.","position":7,"audioStartSeconds":29.878458333333334,"audioEndSeconds":34.70975},{"speaker":"A","text":"Children under twelve can join all weekend sessions completely for free.","position":8,"audioStartSeconds":34.90975,"audioEndSeconds":39.613375},{"speaker":"A","text":"Please remember that advanced booking is required for pottery and painting classes.","position":9,"audioStartSeconds":39.813375,"audioEndSeconds":45.007041666666666},{"speaker":"A","text":"You should bring your own comfortable shoes if you choose hiking.","position":10,"audioStartSeconds":45.20704166666667,"audioEndSeconds":48.983583333333335},{"speaker":"A","text":"We also provide free parking spaces behind the main community hall.","position":11,"audioStartSeconds":49.18358333333333,"audioEndSeconds":53.84854166666667},{"speaker":"A","text":"Feel free to collect an informational leaflet before you leave today.","position":12,"audioStartSeconds":54.048541666666665,"audioEndSeconds":58.54366666666667}],"questions":[{"prompt":"Office location: ______ the central park","answer":"inside","evidenceSentence":4,"evidence":"Our main office is situated inside the central park near the cafe.","explanation":"Người nói cho biết văn phòng nằm bên trong công viên trung tâm (inside the central park)."},{"prompt":"Registration opening time: ______ morning","answer":"Monday","evidenceSentence":5,"evidence":"Registration starts on Monday morning at nine o clock sharp.","explanation":"Việc đăng ký bắt đầu vào buổi sáng thứ Hai (Monday morning)."},{"prompt":"Adult annual fee: ______ pounds","answer":"twenty","evidenceSentence":7,"evidence":"Each adult participant must pay a small annual fee of twenty pounds.","explanation":"Phí thường niên cho người lớn là hai mươi bảng (twenty pounds)."},{"prompt":"Children age limit for free classes: under ______","answer":"twelve","evidenceSentence":8,"evidence":"Children under twelve can join all weekend sessions completely for free.","explanation":"Trẻ em dưới mười hai tuổi (under twelve) tham gia miễn phí."},{"prompt":"Classes requiring advanced booking: pottery and ______","answer":"painting","evidenceSentence":9,"evidence":"Please remember that advanced booking is required for pottery and painting classes.","explanation":"Các lớp học cần đặt chỗ trước là làm gốm và vẽ tranh (pottery and painting)."},{"prompt":"Free parking location: behind the main ______ hall","answer":"community","evidenceSentence":11,"evidence":"We also provide free parking spaces behind the main community hall.","explanation":"Khu vực đậu xe miễn phí nằm ở phía sau sảnh cộng đồng chính (community hall)."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
